# @title Using Counts of A vs B for Preference Index over time
# @title Using Counts of A vs B for Preference Index over time
def ration(df, t1, t2, filepath):
    """
    This method calculates the preference index for Side A vs Side B over time
    and generates a ratio for each. It also plots and saves the results.

    Args:
    df: DataFrame with side 'A' and 'B' data.
    t1, t2: Time slice indices to select the range for calculating the ratio.
    filepath: Directory to save the output files.

    Returns:
    ratio_A, ratio_B: Series containing the preference index over time for A and B.
    """
    tempdf = df.iloc[t1:t2]

    counts_A = tempdf.iloc[:, 1:].apply(lambda row: row.eq('A').sum(), axis=1)
    counts_B = tempdf.iloc[:, 1:].apply(lambda row: row.eq('B').sum(), axis=1)

    ratio_A = (counts_A - counts_B) / (counts_A + counts_B)
    ratio_B = -ratio_A  # Ratio_B is simply the inverse of Ratio_A

    tempdf['Ratio_A'] = ratio_A
    tempdf['Ratio_B'] = ratio_B

    ratio_A.to_csv(os.path.join(filepath, 'Ratio_A_Preference_Index_Over_Time.csv'))
    ratio_B.to_csv(os.path.join(filepath, 'Ratio_B_Preference_Index_Over_Time.csv'))
    plt.figure(figsize=(10, 5))

    plt.subplot(1, 2, 1)
    plt.plot(tempdf.index, tempdf['Ratio_A'], color='blue')
    plt.title('Ratio A')
    plt.xlabel('Frame')
    plt.ylabel('Ratio')
    plt.ylim(-1, 1)

    plt.subplot(1, 2, 2)
    plt.plot(tempdf.index, tempdf['Ratio_B'], color='red')
    plt.title('Ratio B')
    plt.xlabel('Frame')
    plt.ylabel('Ratio')
    plt.ylim(-1, 1)

    plt.tight_layout()
    plt.savefig(os.path.join(filepath, 'Preference_Index_Over_Time.pdf'), transparent=True)
    plt.show()

    return ratio_A, ratio_B

# @title Mean and SEM lineplot
def mean_and_sem_line(df, filepath, side, forward_fill=True):
    """
    Plots the mean and SEM (Standard Error of the Mean) of the individuals' data over frames.

    Args:
    df: DataFrame containing 'frame' and individual columns.
    filepath: Directory to save the plot.
    side: Side being analyzed (used for the title and filename).
    forward_fill: Boolean to specify if NaN values should be forward-filled (default is True).

    Returns:
    None
    """
    frames = df['frame']
    individuals = df.drop('frame', axis=1)
    print('THIS IS THE DATA STRUCTURE YOU WANT TO LOOK AT')
    print(individuals)
    if forward_fill:
        individuals = individuals.fillna(method='ffill')
    numeric_columns = individuals.select_dtypes(include=[np.number])
    mean_values = numeric_columns.mean(axis=1)
    sem_values = numeric_columns.sem(axis=1)
    plt.figure(figsize=(12, 6))
    plt.plot(frames, mean_values, label='Mean', color='k')


    plt.fill_between(frames, mean_values - sem_values, mean_values + sem_values, color='k', alpha=0.5, label='SEM')

    plt.xlabel('Frame')
    plt.ylabel('Mean and SEM')
    plt.title(f'Mean and SEM Over Frames ({side})')
    plt.ylim(-1, 1)  # Adjust y-axis range if necessary
    plt.legend()

    plt.savefig(os.path.join(filepath, f'{side}_Mean_and_SEM.pdf'), transparent=True)

    plt.show()

# @title Mean and Individual lines
def mean_individual_lines(df, filepath, side):
    """
    Plots individual traces with a mean line on top for the provided data.

    Args:
    df: DataFrame containing 'frame' and individual columns.
    filepath: Directory to save the plot.
    side: Side being analyzed (used for the title and filename).

    Returns:
    None
    """
    # Drop the 'frame' column for individual traces
    tempdf = df.drop(columns=['frame'])

    # Plot individual traces with transparency
    tempdf.T.plot(color='k', alpha=0.2, legend=False)

    # Calculate and plot the mean across rows
    mean_values = tempdf.mean(axis=1)
    plt.plot(mean_values, 'k', linewidth=3, label='Mean')

    # Set labels, title, and limits
    plt.xlabel('Time (frames)')
    plt.ylabel('Preference Index')
    plt.ylim(-1, 1)
    plt.title(f'Individual Traces and Mean ({side})')

    # Save the figure
    plt.savefig(os.path.join(filepath, f'{side}_Individual_Traces_and_Mean.pdf'), transparent=True)

    # Show the plot
    plt.show()

# @title Average Trace
def average_traces(directory, csv_list, path_to_graphics):
  df_list = []
  for csv in csv_list:
      df = pd.read_csv(os.path.join(directory, csv))
      df_list.append(df)
  x_df = pd.concat([df['X#wcentroid (cm)'] for df in df_list], axis=1)
  x_mean = x_df.mean(axis = 1)

  y_df = pd.concat([df['Y#wcentroid (cm)'] for df in df_list], axis=1)
