  x_y_df = pd.DataFrame({})
  x_y_df['frame'] = df['frame']
  x_y_df['X#wcentroid (cm)'] = x_mean
  x_y_df['Y#wcentroid (cm)'] = y_mean
  x_y_annotated_df, time_in_a, time_in_b = region(x_y_df)
  trace(x_y_annotated_df, path_to_graphics, 'Merged')
  heat_trace(x_y_annotated_df, path_to_graphics, 'Merged')

