def plotter2(odora_csvs, odorb_csvs, date_folder, odor_directories):
  """
  returns csvs and graphs representing pi and cpi over time, as well as heatmaps and linegraphs for PI over time
  odora_csvs (list): list of dataframes associated with the region columns from odor a
  odorb_csvs (list): list of dataframes associated with the region columns from odor b
  date_folder (string): path to where tyou want to save the OdorA +Odor B PI overtime graph and csv
  odor_directories (list): list of directories where you want to save odor graphs and csvs
  ***make sure you are savaing the right csvs to the right odor paths***
  """
  df = pd.read_csv(odora_csvs[0])
  frame = df['frame']
  odor_a_pi = pd.DataFrame({})
  odor_b_pi = pd.DataFrame({})
  for csv in odora_csvs:
    df = pd.read_csv(csv)
    #print(len(df))
    df = df.drop(columns = ['frame'])
    odor_a_pi = pd.concat([odor_a_pi, df], axis = 1)
  for csv in odorb_csvs:
    df = pd.read_csv(csv)
    #print(len(df))
    df = df.drop(columns = ['frame'])
    odor_b_pi = pd.concat([odor_b_pi, df], axis = 1)
  #have to rename the columns for subject ID, and remove the frame columns
  odor_a_pi.insert(0, 'frame', frame)
  n = len(odor_a_pi.columns) - 1
  odor_a_pi.columns = ['frame'] + [str(i) for i in range(n)]

  odor_b_pi.insert(0, 'frame', frame)
  n = len(odor_b_pi.columns) - 1
  odor_b_pi.columns = ['frame'] + [str(i) for i in range(n)]

  #save the csvs
  odor_a_pi.to_csv(os.path.join(odor_directories[0], 'Odor A PI Over time.csv'))
  #print('Odor A PI:', len(odor_a_pi))
  odor_b_pi.to_csv(os.path.join(odor_directories[1], 'Odor B PI Over time.csv'))
  #print('Odor B PI:',len(odor_b_pi))
  #now that we have the dataframes, lets make the heatmaps and mean+sem graph
  heatmappy(odor_a_pi, odor_directories[0], 'Odor A')
  heatmappy(odor_b_pi, odor_directories[1], 'Odor B')
  mean_and_sem_line(odor_a_pi, odor_directories[0], 'Odor A')
  mean_and_sem_line(odor_b_pi, odor_directories[1], 'Odor B')
  #lets combine both of these
  mega_pi = pd.concat([odor_a_pi, odor_b_pi.drop(columns = ['frame'])], axis = 1)
  n = len(mega_pi.columns) - 1
  mega_pi.columns = ['frame'] + [str(i) for i in range(n)]
  mega_pi.to_csv(os.path.join(date_folder, 'Odor A+B PI Over time.csv'))
  heatmappy(mega_pi, date_folder, 'OdorA+OdorB')
  mean_and_sem_line(mega_pi, date_folder, 'CPI Over Time')
  return odor_a_pi, odor_b_pi, mega_pi






