def plotter4(compare_groups, column_list, genotypes, folder):
  """
  returns graphs comparing metrics for mutliple genotypes
  compare_groups(list): list of paths to csvs that have merged metrics that you want to compare
  column_list:(list of list) columns that you want to compare
  genotypes (list): list of genotypes corresponding to your data, make sure they are in the proper order compare_groups 1 should
  be the for the first genotype
  folder (string): path that you want to save the graphs to
  """
  df_list = []
  for i, path in enumerate(compare_groups):
    df_name = genotypes[i]
    globals()[df_name] = pd.read_csv(path)
    df_list.append(globals()[df_name])
  keys = genotypes
  concatenated_df = pd.concat(df_list, keys=keys)
  concatenated_df.to_csv(os.path.join(folder, 'Omni metrics.csv' ))
  concatenated_df_cleaned = concatenated_df.dropna()
  # Drop rows with NaN values from the concatenated dataframe
  concatenated_df_cleaned = concatenated_df_cleaned.reset_index()
  concatenated_df_cleaned.to_csv(os.path.join(folder, 'Cleaned Omni metrics.csv'))
  melted_df = pd.melt(concatenated_df_cleaned, id_vars='level_0', value_vars=column_list, var_name='Column')

  graphics_path = os.path.join(folder, 'Graphics')
  try:
     os.mkdir(graphics_path)
  except OSError as error:
    pass

  # Loop through each column and create violin plots
  for column in column_list:
      plt.figure(figsize=(12, 6))  # Adjust the figure size as needed

      # Create a violin plot using seaborn
      sns.violinplot(data=melted_df[melted_df['Column'] == column], x='level_0', y='value', split=True, inner="box",
                     palette = custom_palette2)
      sns.swarmplot(data=melted_df[melted_df['Column'] == column], x='level_0', y='value',linewidth=1, size=8, edgecolor= 'k',
                    palette = custom_palette2, alpha = 0.5)
      # Set plot labels and title
      plt.xlabel('Genotype')
      plt.ylabel(column)
      plt.title(f'Violin Plot for {column}')
      plt.savefig(os.path.join(graphics_path, column + ' Violinplot.pdf'))
  for column in column_list:
      plt.figure(figsize=(12, 6))  # Adjust the figure size as needed

      # Create a violin plot using seaborn
      sns.boxplot(data=melted_df[melted_df['Column'] == column], x='level_0', y='value', palette = custom_palette2)
      sns.swarmplot(data=melted_df[melted_df['Column'] == column], x='level_0', y='value',linewidth=1, size=8, edgecolor= 'k',
                    palette = custom_palette2, alpha = 0.5)
      # Set plot labels and title
      plt.xlabel('Genotype')
      plt.ylabel(column)
      plt.title(f'Box Plot for {column}')
      plt.savefig(os.path.join(graphics_path, column + ' boxplot.pdf'))
      # Show the plot
      plt.show()
  return concatenated_df, concatenated_df_cleaned

#@title stats for comparing multiple genotypes (maybe for comparing within genotype odor v odor as well i dont see why not)
def perform_statistical_tests(column, dfs):
    data = pd.DataFrame({key: df[column] for key, df in dfs.items()})
    data = data.dropna()

    # Shapiro-Wilk test for normality
    normality_test = shapiro(data)
    #print(normality_test.pvalue)

    # Levene's test for homogeneity of variances
    homogeneity_test = levene(*[data[key] for key in data.columns])
    #print(homogeneity_test.pvalue)

    result = {'Column': column}

    # Determine if the data is parametric or non-parametric
    if normality_test.pvalue > p_value and homogeneity_test.pvalue > p_value:
        result['Test Type'] = 'Parametric'
        # Parametric tests
        if len(data.columns) == 2:
            # Paired t-test for two dataframes
            t_stat, t_p_value = ttest_rel(*[data[key] for key in data.columns])
            result['Statistic'] = 'Paired t-test'
        else:
            # One-way ANOVA for more than two dataframes
            f_stat, f_p_value = f_oneway(*[data[key] for key in data.columns])
            result['Statistic'] = 'One-way ANOVA'

            # Post hoc Tukey's test
            posthoc_tukey = pairwise_tukeyhsd(data.values.flatten(), np.repeat(data.columns, len(data)))
            result['Posthoc Test'] = 'Tukey HSD'
            result['Posthoc Result'] = posthoc_tukey.summary()
        result['P-Value'] = t_p_value if len(data.columns) == 2 else f_p_value
        print('Parametric')
        print(column)
        print(result['P-Value'])
    else:
        result['Test Type'] = 'Non-Parametric'
        # Non-parametric tests

        h_stat, h_p_value = kruskal(*[data[key] for key in data.columns])

        if len(data.columns) == 2:
            # Mann-Whitney U test for two groups
            u_stat, u_p_value = mannwhitneyu(*[data[key] for key in data.columns])
            result['Statistic'] = 'Mann-Whitney U'
            result['P-Value'] = u_p_value
        else:
          # Kruskal-Wallis test for more than two dataframes
            result['Statistic'] = 'Kruskal-Wallis ANOVA'
            result['Posthoc Test'] = 'Dunn'
            result['Posthoc Result'] = pg.pairwise_ttests(dv='value', between='variable', data=pd.melt(data.reset_index(), id_vars='index'), parametric=False, padjust='holm')
            result['P-Value'] = h_p_value
        print('Nonparametric')
        print(column)
        print(h_p_value)
    return result

