#@title top and bottom csv grabber
def group_my_csvs_please(directory, string):
  """
  """
  output_list_top = []
  output_list_bottom = []
  for root, dirs, files in os.walk(directory):
        if "Top" in root and any(file.endswith(".csv") for file in files):
            for file in files:
                if file.endswith(".csv") and string in file:
                    output_list_top.append(os.path.join(root, file))
        elif "Bottom" in root and any(file.endswith(".csv") for file in files):
            for file in files:
                if file.endswith(".csv") and string in file:
                    output_list_bottom.append(os.path.join(root, file))
  return output_list_top, output_list_bottom

#@title odor a vs odor b
def group_my_csvs_please2(directory, string, odor_a_timestamps, odor_b_timestamps):
    """
    Groups CSV files based on whether they match odor pairing timestamps for both TOP and BOTTOM.

    Args:
        directory (str): The root directory containing the processed data.
        string (str): A string that the CSV file should contain.
        odor_a_timestamps (list of str): List of timestamps for Odor A paired flies for both top and bottom.
        odor_b_timestamps (list of str): List of timestamps for Odor B paired flies for both top and bottom.

    Returns:
        tuple: Two lists - one containing files for Odor A and the other for Odor B.
    """
    output_list_a = []
    output_list_b = []

    # Walk the directory to find CSV files
    for root, dirs, files in os.walk(directory):
        for file in files:
            # Only consider CSV files that contain the specific string in their names
            if file.endswith(".csv") and string in file:
                # Check if the file name contains any of the Odor A or Odor B timestamps
                if any(timestamp in file for timestamp in odor_a_timestamps):
                    output_list_a.append(os.path.join(root, file))
                elif any(timestamp in file for timestamp in odor_b_timestamps):
                    output_list_b.append(os.path.join(root, file))

    return output_list_a, output_list_b



def group_my_csvs_please3(directory, string, odor_a_timestamps, odor_b_timestamps):
    """
    Groups CSV files based on whether they match odor pairing timestamps for specific keys.

    Args:
        directory (str): The root directory containing the processed data.
        string (str): A string that the CSV file should contain.
        odor_a_timestamps (dict): Dictionary of keys and associated timestamps for Odor A.
        odor_b_timestamps (dict): Dictionary of keys and associated timestamps for Odor B.

    Returns:
        tuple: Two lists - one containing files for Odor A and the other for Odor B.
    """
    output_list_a = []
    output_list_b = []

    # Walk the directory to find CSV files
    for root, dirs, files in os.walk(directory):
        for file in files:
            # Only consider CSV files that contain the specific string in their names
            if file.endswith(".csv") and string in file:
                # Check against Odor A timestamps
                for key, timestamps in odor_a_timestamps.items():
                    if key in file and any(timestamp in file for timestamp in timestamps):
                        output_list_a.append(os.path.join(root, file))
                        break  # Once matched, skip further checks for this file

                # Check against Odor B timestamps
                for key, timestamps in odor_b_timestamps.items():
                    if key in file and any(timestamp in file for timestamp in timestamps):
                        output_list_b.append(os.path.join(root, file))
                        break  # Once matched, skip further checks for this file

    return output_list_a, output_list_b

