# Overlay a swarm plot
sns.swarmplot(x='Genotype', y=column, data=combined_df,
              palette=custom_palette, size=5, edgecolor='k', linewidth=1, alpha=0.5)

# Customize the plot
plt.title('Bout Duration (Unpaired) Across Genotypes')
plt.xlabel('Genotype')
plt.ylabel('Bout Duration (s)')
#plt.ylim(-1.2, 1.2)
legend_labels = [f'{genotype} (n={len(df)})' for genotype, df in zip(genotypes, [df1, df2, df3])]
plt.legend(legend_labels)
plt.savefig(os.path.join(graphics_path, column + ' Violinplot.pdf'), transparent =True)
plt.show()

