import os
import shutil

def file_mover(directory):
    """
    Move through a directory and find all folders named "Top" and "Bottom".
    Inside each of these folders, create a 'data' folder, and move all the CSVs
    from the "Top" and "Bottom" folders into their respective 'data' folder.
    """
    for root, dirs, files in os.walk(directory):
        if os.path.basename(root) in ["Top", "Bottom"]:
            data_folder = os.path.join(root, "data")
            if not os.path.exists(data_folder):
                os.makedirs(data_folder)
            for file in files:
                if file.endswith(".csv"):
                    source_path = os.path.join(root, file)
                    destination_path = os.path.join(data_folder, file)
                    shutil.move(source_path, destination_path)
                    print(f"Moved {file} to {data_folder}")



#example usage
