from statsmodels.api.nonparametric import lowess

from scipy.stats import sem
from statsmodels.nonparametric.smoothers_lowess import lowess

def swapbaby(df, paired_side='A'):
    if paired_side == 'A':
        df_num = df.replace({'A': 1, 'B': -1})
    elif paired_side == 'B':
        df_num = df.replace({'A': -1, 'B': 1})
    return df_num
def avgbaby(df_pi):
    mean = df_pi.mean(axis=1)
    sem_value = sem(df_pi, axis=1)
    return mean, sem_value
def smooth_loess(x, y, frac=0.01):
    loess_smoothed = lowess(y, x, frac=frac, return_sorted=False)
    return loess_smoothed
def bin_data(df, bin_size=10):
    num_bins = int(np.ceil(len(df) / bin_size))
    binned_df = df.groupby(np.arange(len(df)) // bin_size).mean()
    print(binned_df)
    return binned_df
def helpmeplz(odora_csvs, odorb_csvs, savepath, t1, t2):
    df_A = pd.concat([pd.read_csv(csv).iloc[t1:t2] for csv in odora_csvs], axis=1)
    df_A = df_A.drop(columns=['frame', 'Unnamed: 0'], errors='ignore')
    df_A_num = swapbaby(df_A, paired_side='A')
    df_B = pd.concat([pd.read_csv(csv).iloc[t1:t2] for csv in odorb_csvs], axis=1)
    df_B = df_B.drop(columns=['frame', 'Unnamed: 0'], errors='ignore')
    df_B_num = swapbaby(df_B, paired_side='B')
    df_pi_combined = pd.concat([df_A_num, df_B_num], axis=1)
    df_pi_binned = bin_data(df_pi_combined, bin_size=300)
    df_pi_binned.to_csv(os.path.join(savepath, 'Individual_fly_preference_Binned.csv'), index=False)
    mean_combined, sem_combined = avgbaby(df_pi_binned)
    frames_binned = np.arange(len(mean_combined))
    mean_smoothed = smooth_loess(frames_binned, mean_combined, frac=0.1)
    sem_smoothed = smooth_loess(frames_binned, sem_combined, frac=0.1)
    result_df_combined = pd.DataFrame({'Frame': frames_binned, 'Preference Index': mean_smoothed, 'SEM': sem_smoothed})
    result_df_combined.to_csv(os.path.join(savepath, 'Mean_SEM_Combined_Ratio_Binned.csv'), index=False)
    plt.figure(figsize=(6.09, 5))
    plt.plot(frames_binned, mean_smoothed, color='purple', label='Smoothed Preference Index')
    plt.fill_between(frames_binned, mean_smoothed - sem_smoothed, mean_smoothed + sem_smoothed, color='purple', alpha=0.3, label='Smoothed SEM')
    plt.title('Conditioned Preference Index with Smoothed SEM (Binned)')
    plt.xlabel('Binned Frames (10-second intervals)')
    plt.ylabel('Preference Index')
    plt.legend()
    plt.tight_layout()
    plt.ylim(-1, 1)
    plt.savefig(os.path.join(savepath, 'Combined_Mean_Preference_Index_Over_Time_Binned_Smoothed.pdf'), transparent=True)
    plt.show()

    return result_df_combined

