# Function to aggregate CSVs from multiple timestamp folders
def aggregate_csvs(base_path, num_timestamp_folders, output_csv_path):
    aggregated_data = []

    # Iterate through the specified number of timestamp folders
    timestamp_folders = sorted(os.listdir(base_path))[:num_timestamp_folders]
    for timestamp in timestamp_folders:
        bottom_csv_path = os.path.join(base_path, timestamp, "Bottom", "Merged_Region.csv")
        top_csv_path = os.path.join(base_path, timestamp, "Top", "Merged_Region.csv")

        # Load CSVs from both Bottom and Top, if they exist
        for csv_path in [bottom_csv_path, top_csv_path]:
            if os.path.exists(csv_path):
                data = pd.read_csv(csv_path)

                # Append data with new column names
                # If this is the first file, we initialize the DataFrame
                if len(aggregated_data) == 0:
                    aggregated_data.append(data)
                else:
                    # To ensure columns are added correctly, we append as new columns
                    # Renaming columns to avoid overwriting (e.g., adding suffix)
                    new_columns = {col: f"{csv_path}_{col}" for col in data.columns}
                    data.rename(columns=new_columns, inplace=True)
                    aggregated_data.append(data)

    # Combine all data into one DataFrame by appending columns horizontally
    aggregated_df = pd.concat(aggregated_data, axis=1)

    # Save the aggregated data to a new CSV file
    aggregated_df.to_csv(output_csv_path, index=False)
    return aggregated_df

# Function to perform the original analysis and plotting
def analyze_aggregated_data(aggregated_df, start_frame, end_frame, bin_size):
    # Filter data between start_frame and end_frame
    filtered_data = aggregated_df[(aggregated_df['frame'] >= start_frame) & (aggregated_df['frame'] <= end_frame)]

    # Initialize an empty dictionary to store results
    results = {col: [] for col in filtered_data.columns if col != 'frame'}

    # Iterate over bins of the specified size
    for start in range(start_frame, end_frame + 1, bin_size):
        end = start + bin_size - 1
        bin_data = filtered_data[(filtered_data['frame'] >= start) & (filtered_data['frame'] <= end)]

        for col in results.keys():
            count_A = (bin_data[col] == 'A').sum()
            count_B = (bin_data[col] == 'B').sum()
            value = (count_A - count_B) / bin_size
            results[col].append(value)

    # Convert results into a DataFrame for easier plotting
    results_df = pd.DataFrame(results)

    plt.clf()

    plt.figure(figsize=(10, 8))
    for i, col in enumerate(results_df.columns, start=1):
        # Generate jitter by adding small random values to x-coordinates
        jitter = np.random.uniform(-0.2, 0.2, len(results_df[col]))
        x_values = np.arange(len(results_df[col])) + jitter  # Apply jitter

        plt.scatter(x_values, results_df[col], label=f'Column {col}', s=10, color='black')

    # Add labels, title, and legend
    plt.xlabel('Bin Number')
    plt.ylabel('Individual Preference Indices (10 second bins)')
    plt.title('Dot Plot of (A - B) / 300 for Each Column Across Bins')


    # Save the plot to a file
    output_plot_path = "/content/drive/MyDrive/11.14.24/IND.pdf"  # Specify your desired save path
    plt.savefig(output_plot_path, dpi=600)  # Save with high resolution
